"""Write the TypeScript copy of the call states (R4.1). `--check` fails when the file is out of date."""

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "services/backend"))
TARGET = ROOT / "apps/desktop/src/state/callStates.ts"


def render():
    from app.calling.state import STATES, TERMINAL

    states = "\n".join(f'  "{state}",' for state in STATES)
    terminal = "\n".join(f'  "{state}",' for state in STATES if state in TERMINAL)
    return (
        "// Generated by scripts/gen_call_states.py from services/backend/app/calling/state.py. Do not edit.\n"
        f"export const CALL_STATES = [\n{states}\n] as const;\n"
        "export type CallState = (typeof CALL_STATES)[number];\n"
        f"export const TERMINAL_STATES: ReadonlySet<string> = new Set<CallState>([\n{terminal}\n]);\n"
    )


def main(argv):
    if "--check" in argv:
        current = TARGET.read_text() if TARGET.exists() else ""
        if current != render():
            print(f"{TARGET.relative_to(ROOT)} is out of date; run scripts/gen_call_states.py")
            return 1
        return 0
    TARGET.write_text(render())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
